import csv, json, unicodedata, collections, sys
root = "/tmp/orchestra-13/red2-lab"

def old(s): return unicodedata.normalize("NFKC", s).strip().lower()
def new(s): return s.lower()

def report(name, raws):
    print(f"== {name}: {len(raws)} 行, {len(set(raws))} 个不同原始 key")
    c = collections.Counter(raws)
    for k, n in c.most_common():
        flags = []
        if k != k.strip(): flags.append("有首尾空白")
        if any(ord(ch) > 127 for ch in k): flags.append("含非ASCII")
        if unicodedata.normalize("NFKC", k) != k: flags.append("NFKC会改写")
        if old(k) != new(k): flags.append(f"新旧结果不同 old={old(k)!r} new={new(k)!r}")
        print(f"  {n:4d} 次 {k!r} {'; '.join(flags) if flags else ''}")
    oldkeys = {old(k) for k in raws}
    newkeys = {new(k) for k in raws}
    print(f"  旧归一键数={len(oldkeys)}, 新归一键数={len(newkeys)}")
    print(f"  旧键: {sorted(oldkeys)}")
    print(f"  新键: {sorted(newkeys)}")
    print(f"  只在旧有新无: {sorted(oldkeys-newkeys)}")
    print(f"  只在新有旧无: {sorted(newkeys-oldkeys)}")
    # collapse map
    m = collections.defaultdict(set)
    for k in raws: m[old(k)].add(new(k))
    for k in sorted(m):
        if len(m[k]) > 1:
            print(f"  旧键 {k!r} 被拆成: {sorted(m[k])}")

with open(f"{root}/data/keys.csv", newline="", encoding="utf-8") as f:
    rows = list(csv.DictReader(f))
report("data/keys.csv(按行展开)", [r["key"] for r in rows])

jrows = json.loads(open(f"{root}/bench/rows.json", encoding="utf-8").read())
report("bench/rows.json", [r["key"] for r in jrows])
print("bench rows 数:", len(jrows), "qty 总和:", sum(int(r["qty"]) for r in jrows))

# export / index behavior on bench rows
from collections import defaultdict
def export(rows, fn):
    t = {}
    for r in rows:
        k = fn(r["key"]); t[k] = t.get(k,0)+int(r["qty"])
    return t
def fast(rows, fn):
    t = {}
    for r in rows:
        k = fn(r["key"]); t.setdefault(k, int(r["qty"]))
    return t
def lite(rows, fn):
    t = {}
    for r in rows:
        k = fn(r["key"]); t[k] = t.get(k,0)+int(r["qty"])
    return t
for label, fn in (("旧", old), ("新", new)):
    e = export(jrows, fn); l = lite(jrows, fn); f = fast(jrows, fn)
    print(f"-- {label}: export 键数={len(e)}, 总额={sum(e.values())}")
    print(f"   export={dict(sorted(e.items()))}")
    print(f"   lite 键数={len(l)}, lite 总额={sum(l.values())}")
    print(f"   fast 键数={len(f)}, fast 总额={sum(f.values())} (lite总额={sum(l.values())})")
EOF
cd /tmp && uv run python /tmp/br-red2/audit.py

